(* [comment removed for export] *)
Definition pf_exitT_stmt (k : nat) (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0x t1x t2x a0 a1 a2 a3 a5 a6 a7 s1x s2x s6x s7x s8x s10x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3x t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (x0 x8 x40 : word) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (g : bool) (j24 : list byte),
  pf_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
         (pf_lows x0 x8 (wz ALOC_TTE_NM) E x40) [CB 24 j24] pv nmc vlc bsz bb (ErrCodeCells E0) g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 ->
  cells_size nmc = 16%nat -> cells_size vlc = 16%nat ->
  In e [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE] ->
  Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 ->
  evt asegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc B E lo shi p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -176)) gp tp t0x t1x t2x (wz E) s1x a0 a1 a2 a3 (wz B) a5 a6 a7
              s2x (wz (E + 16)) (Z_to_bv 64 (bv_unsigned sp + 176)) (wz L) s6x s7x (pick k 1 (shw (E + 16)) (pick k 0 (wz L) s8x))
              (wz 2147450880) s10x (shw (bv_unsigned sp + 176)) t3x t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

Local Ltac pf_exitT_script k e loc LOCT CHK NAV :=
  unfold pf_exitT_stmt;
  intros rax ra sp gp tp t0x t1x t2x a0 a1 a2 a3 a5 a6 a7 s1x s2x s6x s7x s8x s10x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3x t4 t5 t6
         F fc m m1 B E L lo shi p0 bs E0 x0 x8 x40 pv nmc vlc bsz bb g j24;
  intros CTX PURE BSZ SZN SZV HE EV L4 LH;
  pose proof PURE as PURE0;
  destruct CTX as (FRlo & TMP & FRhi & PPC & NMC & VLC & BFC & EC & WIN & LL & TB & HC & ST & MU & WM & MI & SIDE);
  pose proof (pf_pwin _ _ _ _ _ _ _ _ PURE) as FW;
  destruct PURE as (EOK & EF0 & LO & CEIL & APW & APE & EAL & APB & BAL & DWE & DWB & DBE & SPAL & SHI);
  let SHI64 := fresh "SHI64" in
  lazymatch type of SHI with ?x + 216 <= ?y => assert (SHI64 : x + 64 <= y) by (clear - SHI; lia) end;
  pose proof (ex_bnd_intro _ _ _ _ _ LO CEIL SHI64 APE) as BND;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 4104 APB ltac:(lia)) as (BB1 & BB2 & BB3 & BB4 & BB5);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APW ltac:(lia)) as (WB1 & WB2 & WB3 & WB4 & WB5);
  clear BB5 WB5; hydeL DWE; hydeL DWB; hydeL DBE; hydeL EAL; hydeL BAL; hydeL SPAL;
  unfold pf_W, pf_lows, pch_saved, PF_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP, APfTab, APF_TABPTR,
         AL_TAB_IS_TOKEN_LIT, ALOC_TTE_NM in *;
  unfold wz in *;
  assert (D8 : (bv_unsigned sp + -128) mod 8 = 0) by (clear - SPAL; unfold hideL in SPAL; Z.div_mod_to_equations; lia);
  hydeL D8; unfold pick, shw in *; cbn [Nat.eqb];
  pose proof (munch_refl [(lo, bv_unsigned sp); (E, E + 24); (6667152, 6667152 + 64)]%Z m1) as MUx;
  pose proof (wmono_refl asegs m1) as WMx;
  park PPC; park NMC; park VLC; park BFC; park WIN; park TB;
  unfold ErrCodeCells in EC;
